quests[76570] = { id = 76570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Family Business", description = "I was charged with imparting knowledge on every dryad seed. Dionaessa will have retained all of my teachings, but she will be unpracticed in implementing them.\n\nSince it seems you are practiced at completing tasks, you will show Dionaessa the ropes.\n\nA group of lashers have grown strangely restless in the Twisting Wood just outside the garden. Collect some of their hearts so we can discern what has happened.", progress = "The druid Creekward told me lashers tend to lie in wait for their prey.\n\nI'm glad these are not. Makes the fight more interesting!", completion = "These hearts smell awful! Almost as awful as those podlings with the sharp little teeth...", objectives = "Collect 6 Lasher Hearts in the Twisting Wood near the Root-Bound Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76571] = { id = 76571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growth Experience", description = "Dionaessa's connection to Cenarius gives her the ability to grow plants, but she needs space to practice.\n\nThe stirred-up wildlife here will be in your way. The Twisting Wood nearby will have plenty of space with far fewer hooves.\n\n<Melyrine smiles. Her eyes shine with intensity.>\n\nIf she gets poisoned by a podling, don't worry. Dryads are immune to poison. You are not.", progress = "Do you smell that?\n\n<Dionaessa scrunches up her face.>\n\nThe druid Creekward did not describe lashers and podlings as smelling so foul. I have been misled!", completion = "Guardian. If the podlings are poisoning the ground here, then that large growth with the incredible stench over there needs pruning!", objectives = "Have Dionaessa grow 3 flowers in the Twisting Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76572] = { id = 76572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Poisonous Promotion", description = "Guardian! These podlings have been poisoning the lashers, and now they have twisted that mandragora!\n\nIf we do not stop it, it will spread the poison to the garden. This must be what had the wildlife in the garden so disturbed. They were on the verge of invasion!\n\nLet us kill it. This is what you have prepared me for--a dire quest!", completion = "Hey-ah, Guardian! I have never felt more alive than with a spear in hand!\n\n<Dionaessa smiles in a way that bares all of her teeth.>\n\nThank you for your guardianship!", objectives = "Defeat the Sickened Growth in the Twisting Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76576] = { id = 76576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unlikely Proposal", description = "Tuskarr artifacts, underground, deep in Djaradin territory?\n\nIf we didn't find it ourselves I wouldn't believe it. What do you think they were doing down here?\n\nOk looks like the nexus point is right here in this cave. Let's get to the bottom of this!", progress = "I wonder what we'll find?", completion = "Tuskarr and Djaradin trading? I wonder how long that lasted.", objectives = "Observe the Scene from the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76577] = { id = 76577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest in Valdrakken", description = "We've sent some Brewfest shipments off to the Dragon Isles. I've heard they've started some of their own celebrations! Of course ye can't beat the festivities here, but it may be worth paying the dragons a visit!", completion = "Did ye come fer a brew? Hah! We got plenty.", objectives = "Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76578] = { id = 76578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khaz Algar Rally", description = "Race through the checkpoint rings marking the course.", objectives = "Race through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76579] = { id = 76579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest in Valdrakken", description = "Seems the dracthyr have decided to host their own Brewfest festivities this year! Once you've finished celebrating here, you should venture to the Dragon Isles and see what they've put together.", completion = "Did ye come fer a brew? Hah! We got plenty.", objectives = "Speak to Bragdur Battlebrew in Valdrakken on the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76586] = { id = 76586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spreading the Light" }
quests[76587] = { id = 76587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research: Centaur of Ohn'ahran Plains" }
quests[76588] = { id = 76588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender of the Flame", description = "The Expedition forces face formidable adversaries.\n\nDrawn like moths to our keyflames, creatures of all types are intent on snuffing out the light and thwarting our rebuilding efforts.\n\nPlease help us defeat two of the most menacing denizens that threaten our keyflames. Together, we can drive back this darkness.", progress = "Have you eliminated the threats?", completion = "Excellent work, that is two less threats to deal with!", objectives = "Eliminate two rare creatures within the areas controlled by the keyflames.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76591] = { id = 76591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bubbling Brews", description = "Drat! I might've made a mistake asking the dracthyr to help with these deliveries. They've been rolling barrels of brews through the city and crashing 'em all over the place! Well, we shouldn't let the brew go to waste if we can help it!\n\nTake a barrel an' take to the skies! Try to collect and save as much of the brew as you can by collecting the bubbles.", progress = "Have ye filled up the barrel?", completion = "Thank ye kindly for the help. Now if I can just convince the dracthyr to simply fly the barrels here instead of rolling 'em...", objectives = "Collect brew bubbles in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76592] = { id = 76592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Single Wing", description = "Amythora has returned with grave news. The Sundered Flame live on!\n\nWe have been trying to locate and repatriate independent bands of dracthyr here in Valdrakken. I sent Amythora and Marithos to talk to the last of them, but Amythora reports they are a remnant of the Sundered Flame. \n\nAnd they have captured Marithos!\n\nGiven that he used to be one of them, Marithos could be in grave danger. We must investigate and ensure his safety.", completion = "He is badly injured. {name}, we must help him!", objectives = "Look for Marithos in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76593] = { id = 76593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Intentions", description = "Not only did they beat him--they put him in shackles too!\n\nWhat's worse is... I probably would have done the same...\n\nWe will not be able to carry Marithos out of here with this weight chained to him. The key must be around the camp somewhere. Try to find it, {name}, while I keep him comfortable.", progress = "We must free Marithos from his bonds.", completion = "Is that the key, {name}? Good. Let's get these shackles off of Marithos. Then we can start thinking about what to do next.", objectives = "Look for a key to Marithos's shackles in the Lonely Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76594] = { id = 76594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dracthyr Down", description = "What was done to Marithos goes beyond what simple healing can fix. If we expect him to fly out of here, he will need extra care.\n\nThankfully, there are herbs nearby that may give his healing a boost--enough to get him standing, anyway.\n\nLook around and collect some of the Wingfoil nearby, {name}.", progress = "Have you found that Wingfoil? Marithos cannot fly without it.", completion = "Thank you, {name}. Now let's hope for the best...", objectives = "Look for Wingfoil herbs in the Lonely Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76595] = { id = 76595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent Exfiltration", description = "The Sundered Flame here are not going to take Quartermaster Doros's death well...\n\nThey are going to come looking for me. Marithos and Amythora are vulnerable. We cannot let them find us.\n\nSecure the perimeter and keep the Sundered Flame away from Amythora and Marithos.", progress = "If they find us, I do not think the Sundered Flame loyalists will take prisoners.", completion = "I think they are gone. We need to get out of here--now.", objectives = "Keep the Sundered Flame away from Amythora and Marithos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76597] = { id = 76597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On New Wings", description = "I am glad that Winglord Dezran arrived when he did. If he had not, this would have gone... very differently.\n\nWe must take Marithos back to Valdrakken so he can recuperate, but once I have debriefed Dezran, we will send an envoy to help re-introduce them to our people.\n\nThey have suffered. We have suffered. Perhaps now we can all heal.\n\nFollow me back to Valdrakken. We have much to discuss.", completion = "Thank you for your help, {name}. Now that Dezran has returned, we can work to finally bring the dracthyr together.", objectives = "Talk to Emberthal in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76598] = { id = 76598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rough Edges", description = "I apologize for not meeting you in person, {name}, but this method seemed most timely.\n\nOur war against the Primalists has always troubled our queen, but recently she has grown increasingly upset. Something weighs on her. I know how heavy the burdens of the mind can become.\n\nShe left Valdrakken some time ago, saying she needed to find a quiet place to think, but... I am concerned.\n\nPlease--seek her out, and make sure she is all right. She does not need to know I sent you.", completion = "It grieves me to see Vyranoth in such a dark place, but I still have hope that we will stand together as we once did.\n\nI have warned her about Iridikron. That is all I can do.\n\nThe rest is up to her.", objectives = "Find Alexstrasza and check on her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76599] = { id = 76599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Between Gyro-Optics - Activate" }
quests[76600] = { id = 76600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Between the Gyro-Optics", description = "My husband Ezgi loves those harvesters, but I don't trust them, and now you can see why!\n\nThe lights go out, and they all start trying to kill us!\n\nYou want to help me sort this out?\n\nI'm a crack shot with a rifle. You mark the target, and I'll start shooting!", completion = "Ezgi is going to be upset, but you and I did what needed to be done.", objectives = "With Auebry's help, eliminate 8 Dark-Crazed Harvesters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76733] = { id = 76733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tater Trawl", description = "Harvesting in this area has become a challenge, with crazed Harvesters destroying most of our crops. There are potatoes to be found if you look closely.\n\nIf you light the harvest torches, you might uncover some potatoes hiding in the shadows. \n\nUsing those lights, gather as many potatoes as you can. Every bit helps in these trying times.", progress = "Have you found any spuds?", completion = "This is perfect. We love fried potato fingers, we're going to cook up some of those tonight!", objectives = "Light 5 Harvest Torches and gather 15 Firelight Spuds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76734] = { id = 76734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research: Djaradin of Zaralek Cavern" }
quests[76735] = { id = 76735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise in Relic Theft", objectives = "The inns are abuzz with rumors of aspiring criminals pilfering sacred relics.\n\nI'm overseeing the return of stolen goods to their rightful owners. I hear you can be trusted to help.\n\nPlease take this ceremonial tuskarr spear back to Iskaara. And watch out for looters!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76738] = { id = 76738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repeatable Aura Remove" }
