quests[76982] = { id = 76982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sentinel's Summon", description = "Shandris has sent word that she wishes to meet you in Valdrakken.\n\nSeek her out.", completion = "Thank you for coming, {name}.\n\nI will explain the situation.", objectives = "Report to Shandris in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76983] = { id = 76983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Rifts" }
