quests[76992] = { id = 76992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fickle Judgment" }
quests[76993] = { id = 76993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turtle Power" }
quests[76997] = { id = 76997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Shadows", description = "Greetings, {name}. I find myself in a dire situation. \n\nSome fresh recruits and I were on patrol in these lands when our torches went out, leaving us utterly lost and disoriented.\n\nI found safety in this house, but most of the recruits fled, confused into the darkness. \n\nWill you help me locate them? I have a spare Patrol Torch. The mere sight of it should rally them to your side.", progress = "Have you found the recruits?", completion = "The time spent with you is much greater training than I could ever provide these recruits. One of them will remain here to aid you further.", objectives = "Find and rally 3 Demoralized Recruits using the Patrol Torch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77093] = { id = 77093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowflame Axe", description = "The moment you attempted to wield  Fyrakk's axe, Fyr'alath, its flames consumed you. Clearly the weapon's shadowflame was too intense.\n\nPerhaps you should consult an expert on shadowflame and ancient artifacts. Maybe one of the scholars at the Azerothian Archives can deduce a method for handling it safely.", completion = "I say! What do we have here? How curious!\n\nWait a minute...", objectives = "Visit the Azerothian Archives to find an expert on Shadowflame", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77095] = { id = 77095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Tab Barrel", objectives = "Donate to taverns across the Dragon Isles to cover the tab!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
