quests[77097] = { id = 77097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Tab Barrel", objectives = "Donate to taverns across the Dragon Isles to cover the tab!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77098] = { id = 77098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting to Ground", description = "He needs to be healed--now. \n\nWe're too out in the open here. Sundered Flame loyalists could ambush us at any time. \n\nLet's find cover somewhere so we can assess his wounds.\n\nCover me!", completion = "You moved Marithos on your own?\n\nThat was very risky.\n\nBut you were right. Marithos is gravely injured, and we do not have much time.", objectives = "Get Marithos to safety in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77099] = { id = 77099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Tab Barrel", objectives = "Donate to taverns across the Dragon Isles to cover the tab!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77100] = { id = 77100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying the Cliffside", description = "Nothing like brisk ocean air to get you in the mood to dig!\n\nWe're standing in the rubble of an ancient dragonkin fishing village. These dragonkin were ancestors of the blue dragonkin that live on the island today. Humble as it is, the remote location means it's gone relatively undisturbed by treasure hunters.\n\nIf there's anything left that hasn't fallen into the sea, we'll find it!", completion = "<Roska lets out a low whistle.>\n\nWe got to this bad boy just in time, huh? Another hundred years, and it woulda been fish food!", objectives = "Speak with Roska to start the dig then excavate artifacts from the cliffside.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77101] = { id = 77101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingredient Quest Template", description = "Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research.\n\nI had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em!\n\nHelp me wrangle everyone's ideas into one perfect weapon!", objectives = "Help Rocket-Chief Fuselage build the perfect weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77102] = { id = 77102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Hustle", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
