quests[77104] = { id = 77104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Hustle - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77151] = { id = 77151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cache in the Crag", description = "<This barrel is salt-encrusted and buried amongst the rubble but remarkably intact.\n\nIt looks like the sort of mundane cache that villagers would use to store goods, but no one has lived here for thousands of years. Could there still be something inside?\n\nRoska will want to have a look at this!>", progress = "Nothing like a crag, eh {name}? Never know what you'll find!", completion = "Wow, {name}! Not only is this cache intact, but it's full of something other than seawater!\n\nImagine finding great-great-great grandma's jam recipe that'd been lost for thousands of years. Yep, the locals are gonna love this!", objectives = "Speak to Roska to begin carefully excavating the dragonkin cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77152] = { id = 77152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Tab Barrel", objectives = "Donate to taverns across the Dragon Isles to cover the tab!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77153] = { id = 77153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Tab Barrel", objectives = "Donate to taverns across the Dragon Isles to cover the tab!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77154] = { id = 77154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of the Past", description = "Usually, we go to great lengths to avoid busting artifacts open, but I think in this case we'll learn more about the past from what's inside than just staring at a sealed barrel.\n\nThat said, there's someone we should get permission from first. It's her history, after all. In fact, I think she's the only person still around who might have a personal stake in this find.\n\nI'll see to getting this up the cliff. Ask if Atrenosh Hailstone wants to watch us crack 'er open, eh?", progress = "<Roska looks proud of your hard work.>", completion = "That's what this is all about, eh?\n\nConnecting folks with their pasts, making them feel like they're a part of something. It's easier to know where you're going when you know where you came from.", objectives = "Find Atrenosh Hailstone and see if she would like to open the cache with you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77155] = { id = 77155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bar Tab Barrel", objectives = "Donate to taverns across the Dragon Isles to cover the tab!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77156] = { id = 77156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanical Redistribution" }
quests[77159] = { id = 77159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mushroom for Error" }
quests[77163] = { id = 77163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Reason", description = "They seem to know that Sarkareth is gone, but because their missions were so far from Zaralek Cavern, it looks like they never heard how he met his demise. \n\nWe should talk to them. Maybe if they knew why so many of their brethren now follow me they would become Ebon Scales again. Or not...\n\n<Emberthal sighs.>\n\nThis could backfire catastrophically, but I feel like we must try. Quartermaster Doros seems to be in command here. Go and speak to him, {name}. I do not think he would listen to me...", progress = "Find Quartermaster Doros. If you can talk to him, we might be able to avoid a conflict.", completion = "That... did not go as I had hoped.", objectives = "Confront Quartermaster Doros in the Lonely Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77164] = { id = 77164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarab Test One" }
quests[77165] = { id = 77165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Secretive Contact", objectives = "Hey there, I'm a reporter for the Eye of Azeroth.\n\nI'm investigating some strange activity in Valdrakken. Want to help?\n\nI've got a source, but they'll only speak to someone wearing a 'Thinking Cap'. It's supposed to focus thoughts or some such. Anyway, I made a list of the components needed and who you can get them from. \n\nTrack them down, then we'll talk more.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77166] = { id = 77166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Practical Test", description = "Now that you know how to use the device, we will put your skills to the test.\n\nI have attuned your Technoscryers to a valuable item hidden somewhere on this island. Provided you can find it, we will use it to view a scene from the past and deduce how it got there.\n\nIt is time for science! Put... the goggles... on! Resume your scrying!", progress = "Have you found that hidden object, {name}?", completion = "Eureka! Success! \n\nQuickly, hand the Technoscryers back to me. We will readjust them for the next test.", objectives = "Use the Technoscryers to find the hidden object.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77169] = { id = 77169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coilfang Caper", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
