quests[77171] = { id = 77171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coilfang Caper - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77176] = { id = 77176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Can See Through Time!", description = "Okay, the Technoscryers should be calibrated. I have made the same adjustments to my own pair, so we can view the same phenomena.\n\nAre you ready? Put... them on... again! This time, we will use the Observation mode.", progress = "I wonder what we will find?", completion = "Oh, my. Ha ha ha ha ha! \n\nI... conveniently forgot about that. You are not going to tell Nirobin about this, are you?\n\nAcademic rivalry takes many forms. It is all perfectly innocent, I assure you!", objectives = "Observe events from the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77178] = { id = 77178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Withdrawal", completion = "So Fyrakk is after the Wellspring.", objectives = "Return to Alexstrasza in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77191] = { id = 77191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It", description = "If you want to wield Fyr'alath safely, you'll need to modify the weapon's haft with three components.\n\nFirst, you'll need a fireproof hide that can handle intense heat. Next, acquire enchanted vellum that can contain the weapon's volatile magic. Finally, a scribe must apply the proper runes, so you can bind the first two materials to the axe.\n\nMy journal over there includes a few recommendations of crafters who can help you. You might also know a few!", progress = "Please collect the necessary materials quickly. I'm excited to begin.", completion = "Excellent! I knew my instructions would prove sufficient!\n\nOh, and congratulations to you, as well. I commend your diligence.", objectives = "Obtain a Symbiotic Glowspore Grip, a Rune of Shadowbinding, and a Concentrated Sophic Vellum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77192] = { id = 77192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Axe Tempered", description = "Exemplary. Some of the components can be wrapped and attached by hand, but for the last step, you'll need a powerful forge to unify all three in flame.\n\nI've been speaking to Wrathion. He can direct you to a suitable forge in the Obsidian Citadel. I'll meet you both there! I can't wait to see what happens as a result of my ingenious plan!", progress = "We need to attach the modified handle to the axe head. That's more perilous than it sounds...", completion = "Let's prove you can withstand your weapon's corruption.\n\nThe ritual awaits. I can lead you into Aberrus. Are you ready to go?", objectives = "Head to the Obsidian Citadel and ask the smith to forge the handle onto the axe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77193] = { id = 77193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Temptation", description = "Just to be clear: if the axe defeats you, I will be obligated to step in. \n\nBut that's not going to happen, is it? You're not going to be corrupted by shadowflame. You won't devolve into a monstrous, murderous shadow of your former self. I'm not going to have to... intervene.\n\nAs long as we're clear on this, no one is going to have to kill anyone. All right, let's get this done.", progress = "What an intimidating axe!", completion = "We now have something in common: we both share the burden of making something positive out of my father's legacy.\n\nLucky you. Misery loves company. Wield that axe wisely.", objectives = "Talk to Wrathion to travel to Aberrus, and complete the scenario \"A Hero's Resolve.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77194] = { id = 77194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Knot!", progress = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it. I think any of the ogres might have it, but I'm not sure if any specific ones do. Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?! Is that it there??!", completion = "Oh, thank you for freeing me! You - ranked number one. Everyone else - ranked number two or lower.\n\nI knew my life was destined for more than just being an appetizer to some ogre!" }
quests[77195] = { id = 77195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dragon's Eye View", description = "I believe I know just the location for the Netherwing to roost.\n\nIt has a wonderful view and is quite secluded.\n\nI'd like to show our guest some of the sights of Valdrakken before we go. Meet you there?", progress = "Really, the view from the cave is quite remarkable.", completion = "There seem to be far more spiders here than the last time I visited.\n\nBut it seems as if Vyranoth has a plan of action.", objectives = "Travel to the cave above the Sand-Lost Sanctum in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77197] = { id = 77197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Whelping Hand", description = "Well done, {name}.\n\nNow we must ensure the whelps of the netherwing have the best opportunities to grow and flourish. \n\nLet us speak to Mother Elion. I know she would relish the opportunity to care for the young of a new flight. \n\nCan you meet us at the Ruby Lifeshrine?", completion = "Wrathion says there are new whelps on the way?\n\nOf a new flight? Are you certain this is not a joke?\n\nVery well. Let us get started.", objectives = "Meet Mother Elion at the Ruby Lifeshrine in the Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77198] = { id = 77198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home in Time for Tea", description = "I must admit, I did not expect to be altering the future of my flight when I arrived. But it feels as though we belong here. Perhaps this is the call they spoke of...\n\nRegardless, I am looking forward to some rest. \n\nWrathion mentioned retiring to the Roasted Ram Inn. \n\nCan you meet us there?", progress = "I am looking forward to some rest.", completion = "Thanks to you, my flight's safety and future has been secured.\n\nTraveling from Outland to Azeroth has been overwhelming, but in the best of ways.\n\nThe netherwing look forward to exploring this world.", objectives = "Meet Wrathion, Mordenaku, and Vyranoth in the Roasted Ram Inn in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77200] = { id = 77200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offerings for the Well", description = "Amirdrassil has been ushered into this world by the denizens of the Dream. Now we must ensure its roots are bathed in the waters of Elune by creating a new moonwell.\n\nSo many of my people have brought us to this moment. Each should have a part in this dedication. \n\nGo, speak to the kaldorei gathered here, and see if they have offerings for the ceremony.", progress = "Have you collected all the offerings for the ceremony?", completion = "Every kaldorei understands the grief and elation of a moment such as this. The pain we have endured and the hope we have for the future.\n\nThese offerings are profound and appreciated.", objectives = "Gather offerings from night elves in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77201] = { id = 77201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Offering", progress = "Are you certain of your offering?", completion = "An admirable choice. May Elune light your path, {name}.", objectives = "Speak with Tyrande Whisperwind in Central Encampment to choose an offering.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77202] = { id = 77202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Preservationists", description = "Welcome, adventurer. Have you heard the news?\n\nThere's been a rash of artifact thefts as rumors of treasures and secret locations are being exposed.\n\nIf you'd like to learn more, seek out Preservationist Kathos. Your skills at deciphering secrets might help reveal who's behind this chaos.", completion = "A new recruit? Splendid! There's much work to be done, and many secrets to uncover.\n\nReady to get started?", objectives = "Speak with Preservationist Kathos at the Roasted Ram in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77203] = { id = 77203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving Rarities", description = "Let's unravel a secret! Prepare your mind for puzzles...\n\nSpeak to me again when you're ready to start down the path of the preservationists.", progress = "That mystery isn't going to solve itself!", completion = "You unraveled the \"mystery\" and preserved the artifact!\n\nA good preservationist is always looking to get better at preserving artifacts. If you find anything new, we'll figure out how we can employ it in the field.", objectives = "Speak with Preservationist Kathos to begin a secret, then let her know when it's solved.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77205] = { id = 77205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade's Edge Brawl", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77206] = { id = 77206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade's Edge Brawl - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77207] = { id = 77207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blade's Edge Brawl - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77208] = { id = 77208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barreling Down", description = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the Valdrakken folk would hurry up and bring the rest of the barrels down here.\n\nWe've shipped our Brewfest brews here so they can celebrate--and wouldn't ye know it, they've already started their own traditions! Rolling barrels through the city? That's no way to treat a good brew!\n\nMind lending a hand to bring those barrels down here? And try not to break 'em!", progress = "Careful with the barrels! Ye shouldn't jostle a good ale.", completion = "Glad to see that delivery in one piece!", objectives = "Deliver barrels to the Artisan's Market in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77209] = { id = 77209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seed Legacy", description = "For years I worked with Denalan in Teldrassil. His research will be the foundation of how we will restore these seeds.\n\nThe first step: we must coax them back to life, allowing them to grow into vibrant blossoming plants. I have located suitable patches of soil where the plants can take root and grow, revealing their true potential. \n\nWe will plant one small, one plump, and one gigantic seed to observe how the quality of the seed can sprout different growth.", progress = "Have you planted the seeds?", completion = "Denalan would be proud to see his work continued by one such as you!", objectives = "Plant a seed at each of the Dreamsoil patches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77231] = { id = 77231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technoscrying 101", description = "Through a near-perfect blend of technology and arcane enchantment, I have developed a way to analyze the psychometric properties of objects. Wearing these goggles, you can see the data as dynamic simulacra!\n\nSimple, yes? I call it... the Psychometric Visuo-Auditory Discrete Waveform Analysis and Viewing Device! For the layperson, we're calling them \"Technoscryers.\" Trademark and patent pending.\n\nHere, try them on!", progress = "I have given you the Technoscryers. Please! Put them on!", completion = "Well done! \n\nI admit, the bar for putting on a pair of goggles is super low, but still! You did it!", objectives = "Learn to use the Technoscryers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77236] = { id = 77236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Time Needs Mending", description = "We need to close rifts. We need to fix timeways. Honestly, we need all the help we can get.\n\nThere's always more work to do. Are you ready for the next challenge?", progress = "Come now, these rifts aren't going to close themselves.", completion = "Good work out there. \n\nTake a moment and catch your breath, but keep your weapons close at hand. It's been one surprise after another.\n\nFortunately, all this hard work is worth it. Each time rift we close gets us one step closer to fixing the timeways.", objectives = "Close a Time Rift by defeating a Fractured Causality.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77237] = { id = 77237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Thinking Cap", description = "<Take the Unfinished Thinking Cap to Fangli Hoot near the Barber Shop in Valdrakken.>", progress = "<Fangli looks at you, but doesn't speak.>", completion = "<Fangli points to your head, then to hers. She gestures for your Unfinished Thinking Cap.\n\nShe uses an arclight spanner to adjust some wires and lenses, then flips a switch. The Thinking Cap whirs to life.\n\nFangli hands it back to you.>", objectives = "Take the Unfinished Thinking Cap to Fangli Hoot in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77238] = { id = 77238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telaar Tear", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77239] = { id = 77239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telaar Tear - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77240] = { id = 77240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telaar Tear - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77241] = { id = 77241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Foreseeable Friendship", objectives = "I expect great things from you. In fact, I know you have greatness in you.\n\nKeep up the good work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77242] = { id = 77242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Many Invader's Scourgestones", progress = "An Invader's Scourgestone was the insignia of the Scourge's elite troops. These were sometimes found on the stronger of the troops positioned in Stratholme and Scholomance.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", completion = "More and more scourgestones pile up by the day, {name}, from yourself and a growing number of other adventurers.\n\nFortunately, none of our soldiers have mysteriously disappeared nor have I heard more bloodcurdling screams than what is normal for this region.\n\nI would rather not ask questions. Here is your reward." }
quests[77243] = { id = 77243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Many Corruptor's Scourgestones", progress = "A Corruptor's Scourgestone was the insignia of the Scourge's overlords. Powerful beings that once held a position of authority over the Scourge always possessed one.\n\nI formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", completion = "More and more scourgestones pile up by the day, {name}, from yourself and a growing number of other adventurers.\n\nFortunately, none of our soldiers have mysteriously disappeared nor have I heard more bloodcurdling screams than what is normal for this region.\n\nI would rather not ask questions. Here is your reward." }
quests[77244] = { id = 77244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Many Corruptor's Scourgestones", progress = "I doubt I need to give you the entire spiel about scourgestones, {name}, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nCorruptor's Scourgestones are by far the most powerful, so we can talk business if you only have a few.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", completion = "Another batch of scourgestones from my best buddy, {name}! Thanks as always, these will go great with the rest of my hoard. Keep this up, and I will need to find a new place to stash them!\n\nHere's a token for your trouble. I like this little back and forth trading game we got going on here. Let's keep it up.\n\nBut no, I am still not telling you what they're for." }
quests[77245] = { id = 77245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Many Invader's Scourgestones", progress = "I doubt I need to give you the entire spiel about scourgestones, {name}, so I will cut to the chase. I am VERY interested in growing my collection, and you are VERY interested in what I have to offer.\n\nInvader's Scourgestones are rather common, so I ask you bring a decent haul.\n\nAnd don't tell the Argent Dawn about this! It's our little secret, right pal?", completion = "Another batch of scourgestones from my best buddy, {name}! Thanks as always, these will go great with the rest of my hoard. Keep this up, and I will need to find a new place to stash them!\n\nHere's a token for your trouble. I like this little back and forth trading game we got going on here. Let's keep it up.\n\nBut no, I am still not telling you what they're for." }
quests[77248] = { id = 77248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Recognition of Skill", objectives = "Your accomplishments are impressive. \n\nPlease take this as a token of our esteem. Don our colors as you continue mending the timeways.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77249] = { id = 77249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of Us", objectives = "Perhaps you can now see the big picture. Reckless time travel can have consequences, and the damage to the timeways is extensive. \n\nAs you can see, time is a tangled skein. You've untangled many threads, and we all benefit from your diligence. You've proven you're a hero, not just on this world but on many others.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77250] = { id = 77250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Realized Potential", objectives = "I've heard the inhabitants of other timeways are singing your praises. You're not just a hero in this world. Your name is spoken with reverence in other dimensions.\n\nAre you sure you aren't a bronze dragon?\n\nI jest. Thank you {name}. We couldn't do this without you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77251] = { id = 77251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaping the Dreamsurge", description = "The Emerald Dream is thrumming with energies not felt in ages. \n\nSome of that energy is even slipping through the barrier between the dream and Azeroth, coalescing into a glimmering, pollen-like powder. \n\nGather as much as you can. This is not like any event we have seen before!", progress = "The winds sparkle with motes of dreaming essence, spreading it over the land.", completion = "Thank you, {name}. This will aid us greatly in understanding what marvels we are witnessing.", objectives = "Gather Dreamsurge Coalescence from around the Dreamsurge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77254] = { id = 77254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: Time Rift", description = "The Bronze Dragonflight have long labored in secret, dealing with temporal anomalies nearly as quickly as they're able to manifest. It would appear, however, that the anomalies have gotten a bit too big as of late.\n\nThat's where you come in.\n\nYou can find Soridormi leading an effort against a particularly nasty set of Time Rifts just to the east of Valdrakken. Aid her in whatever way she deems necessary.", progress = "Do you bring news of your success?", completion = "The work of the Bronze is never complete, is it?\n\nPlease accept this humble gift, along with our gratitude.", objectives = "Travel to the Tyrhold Reservoir and assist Soridormi in dispelling a Time Rift. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77260] = { id = 77260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorthorn Rise Rush", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77261] = { id = 77261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorthorn Rise Rush - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77262] = { id = 77262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorthorn Rise Rush - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77263] = { id = 77263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Torch of Pyrreth", description = "Let's begin with a simple test.\n\nI have hidden an artifact somewhere in the Ruby Enclave.\n\nIf you have the torch out, it should illuminate when you get close to the target. And if my theory is correct, it should interact with a lock I put on the artifact.\n\nBring me back what's inside. Got it?", progress = "Return when you have retrieved what I ask.", completion = "Ah yes, my field glasses. I must have set them inside it by accident.\n\nI couldn't figure out how to open it again. But you could!\n\nThank you, {name}.", objectives = "Use the Torch of Opening to unlock Kathos' artifact, hidden somewhere in The Ruby Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77264] = { id = 77264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun Coaster", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77265] = { id = 77265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun Coaster - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77266] = { id = 77266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun Coaster - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77267] = { id = 77267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation 101", description = "So, you want to learn how to excavate artifacts? You came to the right orc!\n\nTurns out being able to shape the earth is useful when you're trying to get stuff out of the ground. And given how much the elements affect our work, it helps having an elemental to lend a hand.\n\nBut you don't have to be a shaman to master excavation. I've got the elements covered. I'll just walk you through the detail work.", progress = "What do you think? Having fun yet?", completion = "That's a find, all right! Look at you. You're a natural at this!", objectives = "Meet with Roska outside to learn about excavation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77268] = { id = 77268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hands-On Experience", description = "Great job on that small find! Now, are you ready for something big?\n\nMore often than not, shaking up the small stuff will shake up something even BIGGER just below the surface. Another little rumble, and we'll have a major find on our hands, I can feel it.\n\nA major find works almost the same as the smaller ones with a couple extra steps. Why don't you tackle this one too? It'll be good practice for ya.\n\nDon't worry! I can guide you through it.", progress = "Rare to find big stuff like that up here! Zenata might be up to her tricks again.", completion = "Look at you, master excavator! I reckon you're about ready to get into the field.\n\nSee you out in the dirt!", objectives = "Unearth the major find, then speak to Roska to begin excavating it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77276] = { id = 77276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Inside Job?", description = "Fangli Hoot says they have a theory on who might be stealing the artifacts.\n\nSeek her out again near the Barber Shop.", completion = "I have a theory. What if this so-called \"Preservationist\" is stealing the artifacts, then having you return fakes instead?\n\nI'll give you the location of a box where the Preservationist is keeping artifacts. Grab one, then follow these coordinates to an appraiser who can verify if what you find is legit.", objectives = "Speak with Fangli Hoot near the Valdrakken Barber Shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77277] = { id = 77277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preservationist Cleared", description = "Ya better return the item before the Preservationist notices it's missing.\n\nThen let Fangli know that her theory didn't pan out.", progress = "What did you discover?", completion = "Really? I was pretty sure they were the perpetrator... \n\nOh well, I've got other leads to follow. I'll let you know when I'm ready to move on 'em. \n\nI'll take that key back, too.", objectives = "Return the Burial Banner to the Preservationist's Locker in the Roasted Ram.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77278] = { id = 77278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempest Keep Sweep", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77279] = { id = 77279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempest Keep Sweep - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77280] = { id = 77280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempest Keep Sweep - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77281] = { id = 77281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing an Artifact", objectives = "One of the Preservationist's colleagues left this note.  \n\nIt says the Primalists are threatening the Life-Binder Conservatory and an important artifact is at risk. I need you to locate and secure it before the looters do. \n\nThe coordinates on the note should work with that funny looking \"Thinking Cap\" you have.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77282] = { id = 77282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact Secured", description = "<Returning the torch to Preservationist Kathos might give insight into how it was used.>", progress = "Welcome back adventurer, have you found something?", completion = "You found the Torch of Pyrreth! There are stories about this in the archives. You say the Preservationists sent a dispatch on it? \n\nIt's said that the torch can enable ancient devices and illuminates when near other artifacts. I have a way for us to test it out.\n\nHere, you take the torch and keep it safe.", objectives = "Return the Torch of Pyrreth to Preservationist Kathos in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77283] = { id = 77283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Multi-Front Battle", description = "The kaldorei have set up a temporary base beneath the boughs of Amirdrassil.\n\nWith hope and hard work, this encampment will become permanent when the tree enters our world. \n\nFeel free to acquaint yourself with the provisions available. Then return to me.", progress = "Have you found what you needed here in camp?", completion = "Tyrande has gone to investigate the Druids of the Flame, learn more about their purpose in the Emerald Dream, and identify their leaders.\n\nHow could night elves and Dream denizens turn to the flame?\n\nI am confident that you and Tyrande can find the answer.", objectives = "Meet Saelienne in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77284] = { id = 77284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Chilling Ascent", objectives = "There's a clerk at General Supplies who's been one of my sources for juicy rumors.\n\nThey told me about an expedition to Vakthros in the Azure Span. Sounds like someone was looking for that torch you found.\n\nThe clerk saw their map and wrote down some coordinates. Hopefully they'll get you close.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77286] = { id = 77286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Knowledgeable Descent", description = "<The rubbing is in an ancient language. Perhaps Bobby Carlisle can get the text translated.>", progress = "Did you find anything?", completion = "You found someone trapped up there? And others were dead? Good thing you had that torch! \n\n<Bobby peers at the etching.>\n\nI don't recognize this text. I'll show it to Preservationist Kathos. Hopefully whatever it says can help us figure out what this group is after.", objectives = "Take the Unveiled Tablet Rubbing to Bobby Carlisle in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77303] = { id = 77303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Idol Searching", objectives = "Another note from Kathos' order just arrived.\n\nIt says that a Maruuk artifact hidden within one of the burial mounds of the Eternal Kurgans is at risk. The note mentions ancient incense concealing the artifact from outsiders.\n\nThe rest of the info is in this note. Best of luck, adventurer!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77304] = { id = 77304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Idol in Hand", description = "<The idol appears to be a figure of Ohn'ahra carved from serevite, an ore used in many titan temples.\n\nPreservationist Kathos would surely be interested in this.>", progress = "What have you found?", completion = "You found the Idol of Ohn'ahra! I suppose I shouldn't be surprised.\n\nWe need to get artifacts like this back to their rightful places. But if my superiors are right, we can't risk letting them fall into the wrong hands. \n\nLet me examine the idol.", objectives = "Return the Idol of Ohn'ahra to Preservationist Kathos in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77305] = { id = 77305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Sands", description = "<The Time-Lost fragments are now joined to form a stone tablet, but many of its inscriptions are worn and incomplete.\n\nPreservationist Kathos will want to see this.>", progress = "XENO! How was your luck in the Shifting Sands? Did you find the tablet fragments?", completion = "Ah yes, I can see a portion of the tablet's inscriptions. Many, but not quite all...\n\nI'll pore over these symbols. With luck, I may complete the puzzle and tease out its meaning.", objectives = "Return the Incomplete Tablet to Preservationist Kathos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77310] = { id = 77310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memory of the Dreamer", description = "In the Dream, memories can live on in unusual ways. Memories are not always linear. And memories that are not of your own can become yours.\n\nPerhaps you were drawn to this place by the presence of the once-Dreamer. Or perhaps you were drawn to this place because of my great friend. Come, won't you see?\n\nRest here and let the magic of the Dream wash over you.", completion = "Good that you are here, {name}. Perhaps you can lend your assistance?", objectives = "Rest at the Eye of Ysera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77311] = { id = 77311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing Helper", description = "Gracus sent word for Ysera to come and see him. We arrived and found him in a dire condition. \n\nOur efforts to heal him so far have proved fruitless. But now that you are here, you can assist.\n\nGracus is of the Dream. Perhaps infusing his roots with something grown here will be the final thing we need to restore him.", progress = "Gracus' condition is dire. We must do what we can to try to help.", completion = "I was so certain we could help.\n\nYsera seems to be sensing something here that I cannot. After all she has been through, it seems her magic has indeed changed beyond my recognition.", objectives = "Use the Root Restoration Fruit to help heal Gracus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77312] = { id = 77312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature Persists", description = "Admittedly, I do not know what to do next.\n\nIf he is to rest here... flowers would be lovely.\n\nThe podlings in this area have been hiding among the flowers. Retrieve seeds from them, Champion, and I will make them bloom.\n\nI think Gracus will like the flowers.", progress = "There must be something more that we...\n\nNo. Ysera seems certain.", completion = "Encouraging new growth on an occasion such as this feels right.", objectives = "Collect 6 Sprouted Seedlings from Sneaky Podlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77313] = { id = 77313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Solemn Summons", description = "It is as I feared. It is Gracus' time. \n\nHealing him would never have worked. The world beyond already calls to him. \n\nAlthough he has such peace, those that care for him will still grieve. He will still be dearly missed. \n\nNot everyone is granted a chance to say goodbye. \n\nWe must ensure that in this case, they are.", progress = "I am grateful we can give them this opportunity to say goodbye.", completion = "There is a sense of peace in this place.\n\nGracus summoned me here for a reason. He knew.", objectives = "Inform Gracus' loved ones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77314] = { id = 77314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requiem in a Dream", description = "As one life ends so too will a life begin. \n\nWe must remind those that love Gracus of this, {name}. \n\nPlant seeds around Gracus. My sister can handle the rest. \n\nThis place will not only represent an end but also a beginning of new life.", progress = "These flowers will bloom around Gracus and serve as a reminder of all he helped to grow during his life.", completion = "Those memories... Gracus suffers. We should aid him.", objectives = "Plant 6 flowers around Gracus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77315] = { id = 77315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Memories", description = "Those dark memories cannot be allowed to fester in the Dream.\n\nUnleashing them was necessary. Gracus needed to let go. But if they linger, they may become malevolent.\n\nDefeat the memory that haunts him most so that Gracus can slumber at last.", progress = "Грак не может в полной мере обрести покой, пока его терзают воспоминания.", completion = "Thank you, {name}. Gracus will be at peace now.\n\nAs will those who cared for him, it seems. It is not often people get a second chance to say goodbye.", objectives = "Kill the Lingering Torment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77316] = { id = 77316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Tree", description = "{name}! Merithra needs your help. \n\nSome nasty trickster spriggans followed us into the Dream and now they're causing all sorts of havoc!\n\nLike the most important thing of all, stealing top secret super important supplies. \n\nIt's urgent you stop them and get the supplies back.", progress = "If we don't get those supplies back from those pesky spriggans, we'll be so behind schedule!", completion = "What a relief!\n\nNow that we got those very important supplies back, we can get back to work around here.", objectives = "Retrieve 6 Very Important Tree Supplies from Spriggans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77317] = { id = 77317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatted Hibernation", description = "I'll let you in on a secret, these crates? They're prank supplies! \n\nPeople are so serious around here. What's better than a little prank to lift everyone's spirits?\n\nYou could put some of these fun hats on some of the sleeping druids because what's more fun than a surprise hat?\n\nBe careful though, their connection to the dream could make anything happen!", progress = "Napping in the Dream... I wonder what they're dreaming about!", completion = "I'm impressed. I thought I was pranking you too!\n\nBut looks like you're better at this than I expected... \n\nMaybe it's time for a real challenge.", objectives = "Put 6 silly hats on Dreaming Druids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77318] = { id = 77318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merithra Says", description = "Some druids are volunteering to help tend to the tree and set up camp.  \n\nBut they're so sad! \n\n<Lady Moonberry grows a mischievous grin.> \n\nWe have to give them a reason to smile. You can give them some orders that remind them to have fun. \n\nBut there's no way they'll take orders from you. \n\nThat's why I got this costume for you. With this and a little spell they'll for sure listen to you!", progress = "You're clearly a master prankster but you'll have to be a master actor as well.  \n\nA costume and a spell can only do so much.", completion = "Your performance as Merithra was unmatched.\n\n<Lady Moonberry bursts into laughter.> \n\nI can hardly tell you two apart!", objectives = "Give instructions to 5 druids while disguised as Merithra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77322] = { id = 77322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattrath City Sashay", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77323] = { id = 77323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattrath City Sashay - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77324] = { id = 77324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattrath City Sashay - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77325] = { id = 77325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Archives!", description = "Are you a scholar, historian, or a high-minded intellectual? Do you enjoy heavy, mindless labor in exchange for gold?\n\nThen take hold of your future, and join the newly budding ranks of the Azerothian Archives!*\n\n<Your eyes move to the fine print near the parchment's edge.>\n\n*Temporary offices are located at the Algeth'ar Academy in northern Thaldraszus.", completion = "Finally! The delivery {class} is here with our meal orders!\n\nOh... you're here to join the Archives? Of course! My mistake.\n\nBut if you do see a delivery person around, please point them my way, would you?", objectives = "Speak with Lead Archivist Eadweard Dalyngrigge at Algeth'ar Academy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77327] = { id = 77327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nirobin and the Office", description = "Perhaps there is more to investigate, but I need time to go over our findings here first.\n\nOur colleague, Nirobin, the one arcane projecting himself into the headquarters, should be ready for your assistance by now. He's got his own office at the Academy in Thaldraszus that he tends to squirrel himself away in.\n\nI'm positive he'll be there... Mostly because he never leaves it.", completion = "Are you the new recruit? \n\nSince you're late, I simply assumed you had been swallowed up by the outside... like I am in my ever-reoccurring nightmares.\n\nIt's nice to meet you in person, I suppose.", objectives = "Speak with Nirobin at his office in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77328] = { id = 77328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Headquarters!", description = "Eadweard called for your return to the main office after I'd finished with you... er, this experiment, I mean.\n\nI'm sure it has to do with pomp, circumstance, reward, and what have you. If any of that entices you, then best hurry before his bag of goodies runs dry to all the other recent recruits.", completion = "Good show, {name}!\n\nI had heard high praise of you from Roska and Zenata, but hearing from Nirobin as well... Well! You must be truly exceptional. He has, shall we say, discerning taste!\n\nBut enough about that. You've done more than enough to consider yourself a premier Azerothian Archivist.\n\nWelcome to the team!", objectives = "Meet with Eadweard Dalyngrigge at Algeth'ar Academy in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77329] = { id = 77329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auspicious Gathering", description = "As you know, Amirdrassil is no ordinary tree. Tyrande Whisperwind and the rest of the kaldorei have been preparing to properly welcome it with a ceremony of their own, and establish a new moonwell. \n\nI am certain that Tyrande would want you there for the dedication.\n\nLet us join them at the Central Encampment.", completion = "Amirdrassil is everything we had hoped for. Let us properly honor its arrival.", objectives = "Speak with Tyrande Whisperwind in the Central Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77331] = { id = 77331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graduation Day", description = "You've turned out to be quite a fine member of our high-skilled crew of rag tags and diggers of dirt.\n\nBetween the sites you've broken ground on with Roska, Zenata, and Nirobin, as well as the larger one in Traitor's Rest, the varied histories collected by these Dragon Isles have never been more ripe for the harvest.\n\nThere will always be work and companionship here when you desire it. We hope you'll join us on other continents as well.\n\n...When we receive appropriate funding, that is.", progress = "Worry not. I've already written to our benefactors of your efforts.", completion = "To you, {name}! \n\nTo your supportive efforts, to your spirit of discovery, and to your care for history!\n\nMay all those with joyfully voracious appetites for learning find homes and friends like these!", objectives = "Receive congratulations from your Azerothian Archivist peers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77339] = { id = 77339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Recovery", description = "After a lot of rigorous training, the time has come! Travard believes the Tyr's Guard is ready to recover the disc of Tyr from the Nighthold. \n\nMeet us at Tyr's Rest, the new Tyr's Guard headquarters. It's just south of Tyrhold. \n\nWe will finally make Tyr whole again!", completion = "There you are, {name}. Ready to finally get that disc?", objectives = "Meet Travard at the Tyr's Guard headquarters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77340] = { id = 77340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating the Nighthold", description = "The information from our beacons suggests that Elisande has locked the disc away in Astromancer's Rise.\n\nIt is a place of learning, and the inside will have minimal protection. I have opened a portal where you and the Tyr's Guard will have the least resistance... except for Elisande and whatever guards are under her employ.\n\nAll of you are on your own once you get there, so try not to muck it up.", progress = "I wonder what Tyr is like? I bet he's super nice!", completion = "Glad everyone made it, {name}! We have the disc, the Silver Scale, and Tyr is reforged. Amazing, let's bring Tyr back!", objectives = "Retrieve the Disc of Tyr from Elisande in the Nighthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77341] = { id = 77341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Logotyrapy", progress = "Tyr seems restless. Perhaps you could talk to him, {name}?", completion = "I hope, {name}, that we can find the greater purpose for which we've been reforged. For both Tyr, and the Tyr's Guard.\n\nPerhaps that search is the next step of our journey.", objectives = "Speak with Tyr at Tyr's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77342] = { id = 77342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disc Delivery", progress = "Did you place the disc in the titan console?", completion = "Tyr is with us once more. I can hardly believe it. Thank you, {name}.", objectives = "Insert the Disc of Tyr into the titan console.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77343] = { id = 77343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tyrful Reunion", progress = "One moment, {name}--I want to hear what Tyr and the aspects are saying!", completion = "I almost can't believe we've arrived at this moment, {name}. So many years spent serving the Tyr's Guard, seeing those watching Tyr's tomb die out--and now both he and the Guard are alive again!", objectives = "Listen to the Aspects' conversation with Tyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77344] = { id = 77344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Process", description = "Tyr is back after thousands of years. I don't even know how many thousands. His world has changed more than we can even imagine. He's going to have many questions and need answers. \n\nMeanwhile, there's nothing any of the Tyr's Guard would rather do than talk with Tyr. Tyr's Rest seems like the perfect place to give him time, answer questions, and process those answers. Would you ask him to join us there?", progress = "We certainly live in interesting times, {name}...", completion = "It is so good to be able to talk with Tyr directly. We have so much to tell him, and I know we all want to ask him questions. \n\nThank you for making this possible, {name}!", objectives = "Invite Tyr to join the Tyr's Guard at Tyr's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77345] = { id = 77345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Need For Higher Velocities", description = "Sometimes you'll need to travel longer distances.\n\nIf you don't need to travel up and over any obstacles using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky.\n\nFollow the rings again to your destination and use Surge Forward when prompted to maintain your speed.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", progress = "Well done, {name}.", completion = "Well done. The rest is now a matter of practice.", objectives = "Fly through the rings and land in the target area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77346] = { id = 77346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Slam", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
