quests[77362] = { id = 77362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research: Drakonid of Forbidden Reach" }
quests[77377] = { id = 77377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Tyrhold! For Tyr!", description = "We recovered. We trained. And now it's time to face Elisande. \n\nCome with us to Tyrhold where Nozdormu, Chromie, and Eternus are waiting to send us to the Nighthold.\n\nWe will get that disc, and Tyr will finally be with us once more.", completion = "Are you sure you are ready to go to the Nighthold?\n\nAre you sure you know what you are up against with this \"Elisande\"?", objectives = "Speak with Eternus in Tyrhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77398] = { id = 77398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eco-Dome Excursion", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
