quests[77400] = { id = 77400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eco-Dome Excursion - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77408] = { id = 77408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophecy Stirs", description = "Prophet Velen has roused from meditation and he requests your immediate presence.\n\nA matter of great import has come to his attention. He would value both your wisdom and strength in addressing it.\n\nThe Prophet awaits you aboard the Vindicaar.\n\nTake this crystal. Our artificers have attuned it to the ship's teleportation matrix.", progress = "I am thankful that you could make this journey.", completion = "Fear not, {name}. For once, the situation is not dire.\n\nIn fact, I am... tentatively hopeful. Though that hope is tempered with concern.", objectives = "Use the Teleportation Crystal to meet Prophet Velen aboard the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77409] = { id = 77409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncertainty", description = "Scattered visions came to me as I meditated. Yellow and red. Shattering glass. A rush of warmth. I see my own hand, but I am afraid to grasp it. The scent of fel--of Argus.\n\nWhen I awoke, a message had been delivered. Hatuun wishes to meet.\n\nAfter the defeat of the Legion, I offered to help Hatuun and his people rejoin us. However, they chose to remain on Argus. \n\nHatuun has seldom reached out to us since then. Perhaps he has reconsidered.\n\nI will make the journey to Krokuun. Please, join me.", progress = "I did not expect Velen to come. He has surprised me.", completion = "Let us see if Velen delivers the aid he once promised.\n\nThere is nothing preventing him this time.", objectives = "Speak to Chieftain Hatuun in Krokuun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77410] = { id = 77410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opening Wounds", description = "My hunters were the ones who found Arzal'kal. They said he helped them fight off several Legion ambushes.\n\nDuring our endless vigil on Argus, we had seen nothing like it. He was not as powerful as some demons, but he was persistent.\n\nHe said he wished to speak with Velen and knew that we had been in contact with him. So, I have fulfilled his request.\n\nIf Velen is all he claims to be, then he would not turn away even the least worthy of his people.\n\nWe will see. I expect little.", progress = "If Hatuun called me here to listen, then I will.\n\nI owe Hatuun that respect.", completion = "Whatever it is that Arzal'kal wishes to show you, please accompany him.\n\nI must stay here and speak with Hatuun in private.", objectives = "Speak to Arzal'kal and listen to what he has to say.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77411] = { id = 77411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contrition", description = "The man'ari have grown desperate since the Legion fell. Some grasp for power. Some isolate themselves. Others have formed cults awaiting the return of Sargeras. They have faith that he will lead them again one day.\n\nNalridun is the leader of one such cult. They are reclusive, but it is rumored that he has seized an ancient relic that Kil'jaeden kept until his death. Nalridun claims to use it to commune with Sargeras.\n\nI believe I know what this relic is. If I am correct, it must be returned to Velen.", progress = "Even if I die here, at least it will not be at the Legion's whim.", completion = "It is done. \n\nOne evil rectified. \n\nIt is all I allowed myself to hope for.", objectives = "Meet Arzal'kal in the Grove of Naroua, then slay Speaker Nalridun and retrieve the ancient draenic relic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77412] = { id = 77412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof and Promise", description = "Reinforcements are unlikely, but the relic is too important to risk. You should return to Prophet Velen with it immediately.\n\nThere is a teleporter just ahead that I can attune to a sigil of my own. It will provide you swift passage.\n\nI will rejoin you later.", progress = "I sense something of great power in your possession.\n\nIt feels... familiar. But placing the memory feels like grasping at sunlight.\n\nDid Arzal'kal lead you to something?", completion = "Is this...?", objectives = "Deliver the Brilliant Star to Prophet Velen in Krokuun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77414] = { id = 77414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreamsurge Investigation", description = "The Emerald Dream bleeding over into Azeroth is unprecedented, {name}. We need to understand exactly what is being affected by this phenomenon if we're to prepare ourselves for what is to come.\n\nPerhaps we can even turn this to our advantage.\n\nHead out into the affected area and see what you can learn. Bring back anything of interest and we will see what can be done.", progress = "How fares the Dreamsurge?", completion = "With this information, {name}, we should be able to shape the Dreamsurge to our advantage. Thank you.", objectives = "Complete activities in the Dreamsurge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77415] = { id = 77415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Hand", description = "Catching him at the very moment he's alone? They must've been watching somewhere nearby but just out of sight. Can you check that cave across the water?\n\nThose hornswogs are known hoarders. If those drakonid left something behind, it may still be there.", progress = "Did you check that cave?", completion = "What did you find?", objectives = "Search hornswog treasure piles for Neltharion agent items.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77417] = { id = 77417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Makes an Infinite", description = "Eternus clearly has something she wishes to impart to us. I am unsure where this conversation will lead. \n\nBut I trust Chromie. If she believes that Eternus can be swayed, I trust her judgment.\n\nWhen you are ready, I will see what she has to say.", progress = "I am interested in learning what Eternus wishes to say.", completion = "So the loss of her sister, Moraidormi, is at the root of everything...", objectives = "See what Eternus has to reveal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77423] = { id = 77423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surging Dreams", description = "Change is coming, {name}. Those attuned to the Emerald Dream can feel it on the wind.\n\nWe need your aid in uncovering what this change entails.\n\nLet us reconvene in the affected area and formulate a plan.", completion = "This nascent \"Dreamsurge\" is affecting us all. We have much to investigate.", objectives = "Meet the druids investigating the Dreamsurge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77424] = { id = 77424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research: Dracthyr of Forbidden Reach" }
quests[77425] = { id = 77425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scale of it All", description = "The Djaradin were trading harpoons with the Tuskarr? I suppose fish harpoons don't cut it when you're dealing with a dragon.\n\nHow big was this shipment do you think? Check around the Zaqali Quartermaster and see if they held onto any ancestral records.", progress = "I know Djaradin aren't normally known for their record-keeping, but there must be something...", completion = "You're back! With good news, I hope?", objectives = "Search near the Zaqali Quartermaster for any record of Tuskarr trading.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77426] = { id = 77426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practice Makes Perfect: Rusziona", description = "Interested in trying to get a faster time?\n\n: Dash forward.\n: Stops forward movement.\n: Restores all Vigor. Must be grounded.", objectives = "Help Rusziona glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77427] = { id = 77427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practice Makes Perfect: Zhusadormu", description = "Interested in trying to get a faster time?\n\n: Tranform into an adult and gain improved speed.\n: Restore 1 Vigor until all Vigor has been recovered.\n: Resets cooldowns.", objectives = "Help Zhusadormu glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77428] = { id = 77428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practice Makes Perfect: Zalethgos", description = "Interested in trying to get a faster time?\n\n: Blink forward and dash.\n: Increases forward acceleration.\n: Consumes Arcane Acceleration and restores Vigor.", objectives = "Help Zalthgos glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77429] = { id = 77429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practice Makes Perfect: Posidriss", description = "Interested in trying to get a faster time?\n\n: Fly up then restore 1 Vigor.\n: Adds 5 sec to Winds of Life's duration.\n: Anytime you restore Vigor, dash forward.", objectives = "Help Posidriss glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77430] = { id = 77430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practice Makes Perfect: Belastrasza", description = "Interested in trying to get a faster time?\n\n: Consumes all Vigor over time.\n: Restore all Vigor, boosting forward each time.\n: Consumes Crimson Flight, resets cooldowns.", objectives = "Help Belastrasza glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77432] = { id = 77432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pedgi the Parched", description = "Pedgi's being dramatic. Again.\n\nI know it seems childish, and that's because it is childish, but he responds well to little treats when he's in a mood.\n\nCould you get him a coffee from the bar downstairs?", progress = "Pedgi's treat should get him to stop moping. By the titans, I can't believe I had to say that...", completion = "I knew musicians were a temperamental sort, but this is ridiculous. At least he's up.", objectives = "Get Pedgi a drink from the inn's bartender.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77433] = { id = 77433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: Riverbed", description = "There's a Riverbed near Maruukai in Ohn'ahran Plains that's teeming with local lore about a lost caravan!\n\nMeet me there as quick as you can! And wear your best, old, mud-ready boots!", completion = "We'll shake up the centaur world with this find!", objectives = "Meet Roska Rocktooth at the Riverbed dig site in Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77434] = { id = 77434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technoscrying: Observatory", description = "My dowsing rods have been pointing towards a set of Drakonid ruins atop a cliff in Waking Shores.\n\nI know not what we'll find, but it's never wise to question the whims of my inventions. They're always 97% correct. \n\nAlways.", completion = "Shall we peek into the past of these crumbling stones?", objectives = "Meet Zenata at the Concord Observatory in Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77436] = { id = 77436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning Barrow", description = "Fyrakk's forces have already set their plans in motion. We are one step behind, and we need to catch up quickly if we are to properly protect Amirdrassil.\n\nWhile you were on your way here, we received word of suspicious-looking figures entering one of the nearby barrow dens. Tyrande already went to investigate. Seek her out and lend her your aid.", completion = "Your arrival is timely, {class}. I require another set of hands.", objectives = "Find Tyrande near the Sor'theril Barrow Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77437] = { id = 77437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eon's Fringe", description = "Timewalker Tempo and their team finally unfroze Eon's Fringe!\n\nEr... mostly. The Timewalkers have things more or less under control but Eon's Fringe has some problems the people of the town wouldn't mind a hand with. \n\nTell Bob I sent ya!", completion = "I'm glad Zera sent you! We have some folks who could use a hand around here.", objectives = "Find Bartender Bob in Eon's Fringe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77483] = { id = 77483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technoscrying: Dragonskull Island", description = "I tuned my various sensors for Dracthyr relics, and they've triangulated a new location for us to investigate off the eastern coast of the Forbidden Reach.\n\nThe local Drakonid tell me it's named Dragonskull Island. Ominous, no?  You're not easily frightened, are you?", completion = "My preliminary sensors are peaking when near the cave entrances. What we're looking for is most certainly inside.", objectives = "Meet Zenata at Dragonskull Cave in Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77484] = { id = 77484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technoscrying: Igira's Watch", description = "Of all places, my sensors are indicating a site of interest beneath the surface in Zaralek Cavern. \n\nBest bring a weapon for this excursion. My preliminary scouting indicated a elevated  presence of both lava and djaradin.", completion = "They seem willing to leave this cave well enough alone, don't they...", objectives = "Meet Zenata at Igira's Watch in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77485] = { id = 77485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technoscrying: Back to Eadweard!", description = "Thanks for all your help!\n\nLet's head back to Eadward and the others back at the Academy to go over all the new information we've uncovered.", sourceObjective = "Meet Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", sourceObjectiveStatus = "unverified-source-field" }
quests[77486] = { id = 77486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: Gaze of Neltharion", description = "A Niffen colleague of mine gave me the underground info about an underground tower. It's decrepit and smack-dab in the middle of Zaralek between Loamm, the Djaradin, and that ghastly lab of Neltharion's.\n\nGrab your favorite shovel and meet me there!", completion = "Let's do as the Niffen do and sniff out these hidden histories.", objectives = "Meet Roska Rocktooth at the Gaze of Neltharion in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77487] = { id = 77487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: Winglord's Perch", description = "We've discovered an ancient fishing village in the Forbidden Reach! It's this humble isle off the northwest coast with its own crumbling bridge and everything!\n\nI'll be there if you're looking for more dirt to dig up!", completion = "{name}! You made it!\n\nThat sea air really wakes you up!", objectives = "Meet Roska Rocktooth at Winglord's Perch in Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77488] = { id = 77488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excavation: Back to Eadweard!", description = "Great job, {name}!\n\nWe've got plenty of history to report back to Eadweard with. Let's meet back at the Academy!", sourceObjective = "Meet Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", sourceObjectiveStatus = "unverified-source-field" }
quests[77489] = { id = 77489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memory Mastery" }
quests[77570] = { id = 77570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuoberon, the Wild Dream of a Child" }
quests[77581] = { id = 77581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill them Gnolls!" }
