quests[77647] = { id = 77647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skettis Scramble - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77653] = { id = 77653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Key Story", description = "Here for the latest? Well, have I got news for you.\n\nA weaponsmith was just here visiting Tithris. Koref, I think? Couldn't help but overhear their discussion about some sort of ancient key. Might be of interest to you, what with all your artifact hunting.\n\nWeaponsmith Koref was headed back to the Obsidian Enclave. You should head there and get the scoop about this ancient key.", completion = "Have you ever heard of the Titan Key? Tall as a dwarf, magically imbued. The titans used a special mold to forge the key, but it's been lost for ages. \n\nHowever, as fortune would have it, Tithris found a book that he believes leads to that very mold! Problem is, the text isn't exactly straightforward. And I'm terrible at reading between the lines.\n\nBut hey, with all your experience finding artifacts, maybe you could give it a shot! I'd be happy to forge the key if you find the mold.", objectives = "Seek out Weaponsmith Koref and interview him about the key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77662] = { id = 77662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Aid", completion = "{name}. Good.\n\nWe have cornered our quarry. Let me brief you on our mission.", objectives = "Meet with Shandris and Lilian in the Lushdream Crags.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77664] = { id = 77664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Step", description = "This operation would not have come this far without Lilian's aid. \n\nWe may not have much in common, but Lillian is a... dependable ally. After fighting side-by-side in the Dream, we have an odd kinship that was forged by this mission.\n\nTogether, we will finish this. With the stones in our hands, it is now safe to take out Raelas and end his little crusade.\n\nOnward.", completion = "That was a... \n\n<Shandris's gaze is locked on something else and she seems deep in thought. She then shakes her head as if to clear it.>\n\nI... Shae'lune would probably like to take a look at these... stones.", objectives = "Eliminate Raelas Firewind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77665] = { id = 77665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound to You", description = "I haven't worked with Shandris long, but... it's unusual for her to act like that.\n\nBut it doesn't matter.\n\nWhile she deals with logistics, you and I should go ahead and find a way to cleanse these stones.\n\nMaybe Shae'lune knows what to do next.", completion = "It will be hard to deal with these stones if Shandris is off somewhere.", objectives = "Ask Shae'lune about the cleansing the stones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77673] = { id = 77673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Surface", description = "I knew coming into this that Shandris likes to work alone, but letting us know where she's going would be nice.\n\nNot a great turn in our professional relationship.\n\nKeeper Sillas won't speak to me...\n\nWe should take a look around the camp. Maybe she left a note or some clue... maybe in her mission log?\n\nTake a look, and see if you can get anything out of Sillas. \n\nI'll wait here in case she comes back.", completion = "I haven't known Shandris for long, but her behavior is out of line.\n\nAnd out of character.\n\nI wonder...", objectives = "Find clues regarding Shandris' whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77674] = { id = 77674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wounds of the Past", description = "It's all making sense now. I believe the missing dream spirit bonded with her--like Cyanthesa said.\n\nIt's making Shandris relive traumatic moments from her life. \n\nIt's not malicious, but the spirit and Shandris are feeding off each others' fears. We have to bring her back to the camp. Shae'lune might be able to help her.\n\nTalk to her. I look like the enemy right now. But maybe she'll talk to you.", completion = "I thought that Shandris was venting her anger on me because I am Forsaken. \n\nI thought now that we had finished the task, she was done with me.\n\nWouldn't be the first time.\n\nBut I'm glad I was wrong. I have come to have... a great respect for her and her abilities.\n\nWe have to help her.", objectives = "Talk to Shandris and help her back to the camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77675] = { id = 77675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Future, Together", description = "{name}, we need to work with Shae'lune and help her perform the purification ritual on Shandris.\n\nShae'lune says she's only done it on objects before--not people. There is some... risk involved.\n\nBut I've come to know Shandris. She'd do the same for me.\n\nTalk to Shae'lune and follow her instructions.", progress = "I will help Shandris as best I can. It's the least I can do for another soldier.", completion = "Thank you, {name}, for helping us with Raelas and with the spirit stones.\n\nI will take care of Shandris for now and help her back to Amirdrassil soon.", objectives = "Help Shae'lune perform the separation ritual on Shandris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77677] = { id = 77677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Water...", description = "<The plant is clear of soot and flame, but its leaves are limp with thirst. Perhaps someone from Central Encampment will know the perfect remedy.>", progress = "<The plant's leaves are fringed in brown and brittle along the edges.>", completion = "<The plant seems partially revitalized, and its leaves dip briefly towards you, as if in thanks.>", objectives = "Nurse the plant back to health.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77679] = { id = 77679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Soridormi's Aid", description = "Have you heard? Time rifts are opening in Tyrhold Reservoir! It's a catastrophe! Folks have seen portals to other timeways randomly appearing. Now all kinds of fantastic creatures are swarming into Azeroth.\n\nThank goodness for Soridormi. I heard she's getting everyone organized to make a stand. If you can offer any assistance, I'm sure she could use it.\n\nThey say she's still stationed in Tyrhold Reservoir. Do it for Valdrakken. Do it for Azeroth!", completion = "We're facing dangerous anomalies called \"time rifts.\" We've been a little too reckless with our time travel. Now creatures from alternate timeways are entering our world, and we need to push them back.\n\nThe situation is quickly getting out of hand. We could use any help we can get. Do what I say when I say it, and we can all prevent the fabric of reality from unraveling.\n\nYou look like you can handle the challenge. Get out there and fight!", objectives = "Speak with Soridormi in Tyrhold Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77681] = { id = 77681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alerting all Adversaries!", description = "The Artisan's Consortium has struck another deal with the quartermasters of the Gladiator's Refuge!\n\nIn addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas!\n\nPresent this leaflet to Calderax to receive two complimentary Trophies of Conquest, on us!\n\n- Rabul", completion = "Wait... is this what I think it is? Are we doing this promotion AGAIN? You have no idea how many of these fliers I got last time.\n\nWell, here are your trophies, as promised. Use them when crafting your own equipment or submitting Crafting Orders and the gear will be comparable in power to what I offer. It is perfect if you are looking for something highly specific or imbued with a certain embellishment... and are willing to put in some extra work.\n\nQuestions? Take them to the Artisan's Market.", objectives = "Deliver the leaflet to Calderax in the Gladiator's Refuge of Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77684] = { id = 77684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Pit Fracas", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77685] = { id = 77685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Pit Fracas - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77686] = { id = 77686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Pit Fracas - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77697] = { id = 77697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Food...", description = "<The plant is now a promising sapling and has thrived with the attention you've given.\n\nPeering closely at the plant's leaves, you see its exterior brimming with dew. Perhaps the right food will help the plant even further.>", progress = "<The plant is hydrated, but remains severely underfed.>", completion = "<The soil around the sapling glows faintly.>", objectives = "Bring some fertilizer for the plant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77698] = { id = 77698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77711] = { id = 77711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And a Pinch of Magic", description = "The diligence you've shown here is astounding, {name}. I never suspected that someone who couldn't even find their own bucket, could do something like this.\n\nI think the sapling is almost there, and with my help we can bring it the rest of the way.\n\nTake this totem and place it near some of the weakened, flame-corrupted Roottenders found in the Singing Fen. This should siphon the unstable magical energies out of their bodies and transform it into something we can use.", progress = "Is the totem charged?", completion = "Perfect!\n\nHand it here and I'll release the stored energy into the surrounding soil.", objectives = "Defeat Roottenders while they are under the effects of the Druidic Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77714] = { id = 77714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature Sealed" }
