quests[77739] = { id = 77739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smother the Flames", progress = "Bring me all four spirit stones. We must keep them close so they do not fall into the wrong hands.", completion = "Good!\n\n<Shandris stashes the spirit stones in a small, leather pouch.>\n\nNow, let us put an end to Raelas's madness.", objectives = "Help Shandris and Lilian retrieve the spirit stones from the Sisters of Flame dryads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
