quests[77760] = { id = 77760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Find: Dragonhorn Flute", description = "<This flute is inexpertly hewn out of the horn of a dragon. The cracking around the base suggests the dragon was long gone by the time the flute was made.\n\nThe mouthpiece is strange. It's almost like it isn't designed to be played with the mouth at all but the nose. Could this flute have been crafted by the niffen?\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", completion = "Aha! A curious find. I shall reach out to the appropriate parties immediately, and we can have it documented and returned to its home post-haste.", objectives = "Bring the Dragonhorn Flute to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77761] = { id = 77761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Documenting a Dream" }
quests[77762] = { id = 77762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Hope is Never Without Worth", description = "The plant has matured and is thriving. And with this little corner of our ecosystem restored, we've seen something I've been wishing for since I learned what you were up to: the dreamtalons have returned with their kits!\n\nOne of the grateful mature dreamtalons has offered their services to you, if you wish it.", completion = "If you treat this Dreamtalon like you've treated this plant, they're very lucky indeed.", objectives = "Speak to Professor Ash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77763] = { id = 77763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Find: Waterlogged Ledger", description = "<This leather-bound ledger is so waterlogged it's nearly falling apart.\n\nMost of it is illegible, but the text that has survived is in an ancient draconic dialect. It appears to be lists and lists of ordinary items, with numbers assigned to them-- perhaps a household accounting book?\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", completion = "Aha! A curious find. I shall reach out to the appropriate parties immediately, and we can have it documented and returned to its home post-haste.", objectives = "Bring the Waterlogged Ledger to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77765] = { id = 77765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Documenting a Dream" }
quests[77766] = { id = 77766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Find: Hole-Punched Bakar Tooth", description = "<This milk-tooth came from a young bakar, though the way the bone has yellowed suggests it's thousands of years old.\n\nSomeone has carefully drilled a hole at the top of this tooth to turn it into a bead. Upon closer examination, the tattered remains of a woolen cord can still be seen threaded through it.\n\nEadweard would know how to preserve this find and figure out whom it might belong to.>", completion = "Aha! A curious find. I shall reach out to the appropriate parties immediately, and we can have it documented and returned to its home post-haste.", objectives = "Bring the Hole-Punched Bakar Tooth to Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77777] = { id = 77777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruby Lifeshrine Loop - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77779] = { id = 77779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tale of Sir Thomas", description = "Suzannah... I never thought I would find her. Now we can return to our children, and rest at last. All thanks to you, {name}.\n\nDo you still have my tome? My story has reached its end, and I would see it penned by my own hand.\n\n<Thomas glides his finger across a blank page, spectral ink marking his words.>\n\nPlease return this to the Orphan Matron. And... please apologize on my behalf for frightening her, would you?", completion = "It is over, then? The Headless Horseman is defeated once more, and the fallen paladin is free and at rest.\n\nWhat happened to the people of Lordaeron was horrifying. The least they deserve is peace in death. The tale of Sir Thomas is a harrowing one--a reminder and a warning of what horrors blind zealotry brings. \n\nI am glad that you helped him find his peace, {name}.", objectives = "Return to the Orphan Matron.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77780] = { id = 77780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blossom Witnessed", description = "Amirdrassil has bloomed beyond the confines of the Dream.\n\nLet us venture to the Dragon Isles and see where this new World Tree has taken root.", progress = "It is magnificent!", completion = "<Merithra's face lights up.>\n\nChampion, we are among the very first to see Amirdrassil here on Azeroth. This is truly a precious moment.", objectives = "Speak with Merithra at the Ancient Bough in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77781] = { id = 77781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Enthusiasm", description = "I noticed the festivities have drawn the attention of a few spriggans from Ardenweald. They are curious creatures with... interesting tastes.\n\nTheir pranks have been more than disruptive. Please root them out so the celebration may continue in peace.", progress = "Have you discovered all of them? I have already heard a middling rumor that I suspect they spun up.", completion = "Thank you, {name}. I appreciate their liveliness, but they are not on our guest list tonight.", objectives = "Reveal 6 Spriggan Pranksters in Bel'ameth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77784] = { id = 77784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrhold Trial - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
