quests[77787] = { id = 77787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormsunder Crater Circuit - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77788] = { id = 77788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashphodel Research Notes", description = "<You find some singed research notes on the slain druid. \n \nThe notes detail experiments being carried out by the Druids of the Flame.  \n\nYou learn that they have created an unusual pollen capable of infusing dream flora with their flame-imbued magic. The next stage targets the local wildlife with the same pollen. \n \nQ'onzu would definitely be interested in a sample of the pollen and these notes.>", progress = "<Q'onzu blinks slowly as they stare down at you.>", completion = "That...was devastatingly mundane. Soot and ash, forever unchanged? \n \n<Q'onzu shakes their enormous head.> \n \nNo. I do not like.", objectives = "Collect the Sample of Cinderpollen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77789] = { id = 77789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Severing Ties", description = "Nalridun has recruited a small army of cultists. They believe he speaks for Sargeras through the relic, clinging to every word he says. The same way we clung to our leaders when Sargeras came to Argus. It was a comfort. A hope.\n\nAnd, in the end, empty deception.\n\nBut his followers do not believe they are deceived. They have constructed their own conduits in the area to try to tap into the relic's power. To hear the voice themselves.\n\nThey will try to stop us. We must cut a path through them.", progress = "May their delusions die with them.\n\nWe cannot risk any power they might be adding to Nalridun's rituals.", completion = "I know what it is to be scared. But they had a choice, and they chose to stay on the path that we built atop the smoldering remains of countless worlds. \n\nWhy, when our home was the first of the worlds we destroyed?", objectives = "Slay 10 man'ari cultists and overload 5 Sargerei Conduits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77791] = { id = 77791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling It: Symbiotic Glowspore Grip", description = "I know a crafter who could help temper Fyr'alath. Erden of Clan Shikaar is extremely resourceful. He's performed many experiments with various reagents throughout the Dragon Isles.\n\nHunters are only as good as their weapons. Erden is known for crafting exquisite weaponry with exotic materials. His expertise in various flora and fauna should prove quite informative.", completion = "I see. \n\nThat axe would certainly be painful to wield. Let me think for a moment.", objectives = "Seek out Erden in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[77793] = { id = 77793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Circuit - Storm Gryphon", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
